import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt(), m = in.nextInt();
        ArrayList<ArrayList<Integer>> qirralar = new ArrayList<>();
        for (int i = 0; i < n; i++) qirralar.add(new ArrayList<>());
        for (int k = 0; k < m; k++) {
            int u = in.nextInt() - 1, v = in.nextInt() - 1;
            qirralar.get(u).add(v);
            qirralar.get(v).add(u);
        }
        int s = in.nextInt() - 1;

        int[] masofa = new int[n];
        Arrays.fill(masofa, -1);
        masofa[s] = 0;
        Queue<Integer> navbat = new LinkedList<>();
        navbat.add(s);
        while (!navbat.isEmpty()) {
            int v = navbat.poll();
            for (int u : qirralar.get(v)) {
                if (masofa[u] == -1) {
                    masofa[u] = masofa[v];
                    navbat.add(u);
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(masofa[i]);
        }
        System.out.println(sb);
    }
}

